async function memoryApi(path,{method='GET',body}={}){const b=await bootInfo();if(!b.memory)throw Error('Memory is not configured here.');
 const r=await window.AtlasAuth.fetch('/api/memory'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Atlas-CSRF':b.csrf},body:body===undefined?undefined:JSON.stringify(body)});
 const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Memory did not answer.');return data;}
// The per-user memory switch (§3.4): true, false, or null when unknown. OFF by default (G2): memory runs only after the person turned it on.
async function loadMemory(){const b=await bootInfo();if(!b.memory)return memoryOn=null;try{const r=await window.AtlasAuth.fetch('/api/memory/settings',{signal:AbortSignal.timeout(5000)});const d=await r.json().catch(()=>null);memoryOn=r.ok&&d&&typeof d.off==='boolean'?!d.off:null;}catch{memoryOn=null;}return memoryOn;}
