async function rememberInterview(p,transcript){try{const b=await bootInfo();if(!b.memory||p.sample)return;await loadMemory();if(memoryOn!==true)return; // off unless the person turned memory on; the server refuses otherwise
 const r=await memoryApi('/remember',{method:'POST',body:{localId:p.id,...window.AtlasProfileCore.modelProject(libraryPayload(p),p.roleFrom)}}); // short structured facts only: no conversation text is sent
 if(r.stored)E.log(p,'Remembered a few short facts privately for your next conversation');}catch{/* memory is best effort; the project is already saved */}}
