 try{const m=await memoryApi('');$('memoryOn').checked=!m.off;memoryOn=!m.off;const title=id=>{const local=id.replace(/^project-/,'');const p=profile().projects.find(x=>x.id===local);return id.startsWith('project-')?(p?p.title:'A project from another device'):id.startsWith('conversation-')?'Conversation on '+id.replace(/^conversation-.*-(\d{4})(\d{2})(\d{2})\d+$/,'$1-$2-$3'):id;};
  $('memoryList').innerHTML=m.documents.length?m.documents.map(d=>`<li><span>${esc(title(d.id))}${d.memories!==null?` <span class="tiny muted">· ${esc(d.memories)} memories</span>`:''}</span><button class="quiet" data-forget="${esc(d.id)}">Forget</button></li>`).join(''):'<li class="tiny muted">Nothing remembered yet.</li>';
  $('memoryStatus').textContent=m.off?'Memory is off: nothing is remembered between interviews.':'';}
