  const prev=$('slidePreview');if(prev)prev.innerHTML=`${s.warning?`<p class="validation wait">${esc(s.warning)}</p>`:''}<p><b>${esc(s.title)}</b><br>${esc(s.subtitle)}</p><p>${esc(s.summary)}</p>${s.sections.map(x=>`<h4>${esc(x.heading)}</h4><ul>${x.bullets.map(b=>`<li class="${b.kind}">${b.kind==='interpretation'?'◇ ':''}${esc(b.text)}</li>`).join('')}</ul>`).join('')}${s.dropped.length?`<p class="tiny muted">Removed because the numbers are not in the reference: ${s.dropped.map(esc).join(' · ')}</p>`:''}<p class="tiny muted">◇ interpretation for this context. Everything else restates the reference.</p>`;
