function slidesForm(id,full){return `<div class="slides-form"><label class="field-label" for="slideContext">Slides for a meeting</label><textarea id="slideContext" rows="2" maxlength="800" placeholder="Who is it for? e.g. COO of a mid-size insurer worried about claims backlog">${esc($('recommendQuery')?.value||'')}</textarea>${full?'<label class="check"><input id="slideClient" type="checkbox"/><span>Include the client name (internal use only)</span></label>':''}<button class="btn" data-make-slides="${esc(id)}">Generate slides (.pptx)</button><div id="slidePreview"></div></div>`;}
function duplicatesBlock(r){const d=r.state.duplicates||[];if(!d.length)return '';return `<div class="quality wait"><h4>Possible duplicates</h4><ul>${d.map(x=>`<li><button class="quiet" data-open-record="${esc(x.id)}">${esc(x.title)}</button> · ${x.sameProjectId?'same project ID':'similarity '+esc(x.similarity)}${r.permissions.merge?` · <button class="quiet" data-merge-keep="${esc(r.id)}" data-merge-from="${esc(x.id)}">Merge it into this reference</button>`:''}</li>`).join('')}</ul><p class="tiny muted">Merging keeps one stronger reference; every consultant keeps access and their own contribution.</p></div>`;}
