function ics(inv){const pad=n=>String(n).padStart(2,'0'),d=new Date(inv.slot||Date.now()+864e5),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');
 const start=`${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}T${pad(d.getHours())}${pad(d.getMinutes())}00`;const clean=s=>String(s||'').replace(/[\\;,]/g,m=>'\\'+m).replace(/\n/g,' ');
 return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ATLAS//Reference interviews//EN','BEGIN:VEVENT',`UID:${inv.id}@atlas`,`DTSTAMP:${stamp}`,`DTSTART:${start}`,'DURATION:PT20M',`SUMMARY:${clean('ATLAS project interview: '+(inv.title||inv.project_id||'your project'))}`,
  `DESCRIPTION:${clean((REASON[inv.reason]||'Interview')+'. Open ATLAS and start the conversation: '+location.origin+location.pathname)}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');}
