// JEV impact & category, and the confidential client line (only ever rendered in this workspace).
let jevStatus=null,bootCache=null;async function bootInfo(){bootCache=(await window.AtlasAuth?.boot())||{};return bootCache;}
async function jevAvailable(){if(jevStatus!==null)return jevStatus;const b=await bootInfo();jevStatus=b.jevClassify?b.csrf:false;return jevStatus;}
function jevCard(p){const c=p.client||{},who=[c.name,c.location,c.contact].filter(Boolean).map(esc).join(' · ');const j=p.jev,stale=j&&j.revision!==p.recordRevision;
 const client=who?`<p class="client-line">🔒 ${who}</p>`:'';if(!j)return client+(jevStatus?`<button class="btn score-impact" data-score="${esc(p.id)}">Score impact with JEV</button>`:'');
 const chips=[j.primary,...j.also].map((x,i)=>`<span class="tag ${i?'':'cat-primary'}">${esc(x.label)}</span>`).join('');
 const dims=Object.values(j.scores).map(s=>`<span title="${esc(s.label)} · confidence ${s.confidence}">${esc(s.label)} <b>${s.score.toFixed(1)}</b>/4</span>`).join('');
 return client+`<div class="impact"><div class="impact-head"><strong>Impact ${Math.round(j.impact)}</strong><span>${stale?'answers changed · rescore':'JEV · '+esc(j.model)}</span></div><div class="impact-bar"><i style="width:${Math.max(2,Math.min(100,j.impact))}%"></i></div><div class="tags">${chips}</div><div class="impact-dims">${dims}</div>${jevStatus&&stale?`<button class="btn score-impact" data-score="${esc(p.id)}">Rescore</button>`:''}</div>`;}
async function scoreImpact(id,btn){const p=profile().projects.find(x=>x.id===id);if(!p)return;const csrf=await jevAvailable();if(!csrf){toast('JEV is not configured on this server.');return;}
 btn.disabled=true;btn.textContent='Scoring…';try{const r=await window.AtlasAuth.fetch('/api/jev/classify',{method:'POST',headers:{'Content-Type':'application/json','X-Atlas-CSRF':csrf},body:JSON.stringify({project:window.AtlasProfileCore.modelProject({title:p.title,role:p.role,sector:p.sector,stage:p.stage,answers:p.answers.map((a,i)=>p.deferred[i]?'':a)},p.roleFrom)})});
  const data=await r.json();if(!r.ok)throw Error(data.error||'Scoring failed');p.jev={...data,at:E.now(),revision:p.recordRevision};E.log(p,'Scored with JEV: '+data.primary.label+', impact '+Math.round(data.impact));save();renderProjects();if(project()?.id===p.id&&p.story)renderStory();toast('Scored: '+data.primary.label+' · impact '+Math.round(data.impact));}
 catch(e){toast(String(e.message||e).slice(0,160));btn.disabled=false;btn.textContent='Score impact with JEV';}}
function renderProjects(){if(jevStatus===null)jevAvailable().then(()=>{if(jevStatus)renderProjects();});const q=$('projectSearch').value.trim().toLowerCase(),stage=$('stageFilter').value;const cat=$('categoryFilter')?.value||'all',byImpact=$('projectSort')?.value==='impact';const list=profile().projects.filter(p=>(stage==='all'||p.stage===stage)&&(cat==='all'||p.jev?.primary?.key===cat||p.jev?.also?.some(a=>a.key===cat))&&[p.title,p.consultant,p.role,p.sector,p.stage,p.client?.name,p.client?.location,...p.answers].join(' ').toLowerCase().includes(q));if(byImpact)list.sort((a,b)=>(b.jev?.impact??-1)-(a.jev?.impact??-1));$('projectScope').textContent=`${list.length} project${list.length===1?'':'s'} in ${profile().name} · local records, not company-wide search`;$('projectCards').innerHTML=list.length?list.map(p=>`<article class="project-card ${p.id===profile().lastProject?'selected':''}"><div class="project-id"><span>${esc(p.stage.toUpperCase())}</span>${p.sample?'<span class="tag yellow">FICTIONAL</span>':'<b>↗</b>'}</div><h2>${esc(p.title)}</h2><p>${esc(p.answers[0]?.trim().slice(0,170)||'The project is ready for your first interview answer.')}${p.answers[0]?.length>170?'…':''}</p><div class="tags"><span class="tag">${esc(p.consultant)}</span>${p.sector?`<span class="tag">${esc(p.sector)}</span>`:''}<span class="tag">${p.answers.filter((v,i)=>v.trim()&&!p.deferred[i]).length}/6 topics</span><span class="tag">${E.ready(p)?'Reviewed locally':p.story?'Draft available':'Capture in progress'}</span></div>${reportCard(p)}${jevCard(p)}<button class="quiet" data-project="${esc(p.id)}">Open project <span>→</span></button></article>`).join(''):`<div class="empty-state"><h2>${profile().projects.length?'No matching projects.':'Make experience easier to find.'}</h2><p>${profile().projects.length?'Try a different word or stage.':'Create your first project or explore the labelled fictional example.'}</p><button class="btn" data-action="${profile().projects.length?'reset-search':'new-project'}">${profile().projects.length?'Clear filters':'Start a project →'}</button></div>`;
 const p=project();if(!p||!list.some(x=>x.id===p.id)){$('projectDetail').innerHTML='';return;}$('projectDetail').innerHTML=`<article class="project-detail"><div class="detail-title"><div><p class="eyebrow">PROJECT RECORD${p.sample?' · FICTIONAL':''}</p><h2>${esc(p.title)}</h2><p class="tiny muted">${esc(p.consultant)}${p.role?' · '+esc(p.role):''} · ${esc(p.stage)} · Updated ${esc(fmt(p.updatedAt))}</p></div><div class="actions"><button class="btn primary" data-view="interview">Continue interview →</button><button class="btn" data-action="draft">${p.story?'Open story':'Build draft'}</button></div></div><div class="detail-grid">${E.TOPICS.map((t,i)=>`<div><h3>${esc(t.label)}${p.deferred[i]?' · open':''}</h3><p>${esc(p.answers[i]||'Not captured yet.')}</p></div>`).join('')}</div><details><summary>Show project connections</summary><div class="experience-path">${[["Consultant",p.consultant,p.role],["Contribution",p.answers[1].slice(0,85)||'Still open','Individual, not team-wide'],["Project",p.title,p.stage],["Evidence",p.sources.filter(s=>s.active).length+' active sources',p.sources.filter(s=>s.active&&s.inspected).length+' inspected'],["Story",p.story?.title||'Not drafted',E.ready(p)?'Reviewed locally':'Working record']].map(a=>`<div><span>${esc(a[0])}</span><strong>${esc(a[1])}</strong><small>${esc(a[2])}</small></div>`).join('')}</div></details><details><summary>Revision history · local record</summary>${p.audit.map(x=>`<div class="audit-line"><time>${esc(fmt(x.at))}</time>${esc(x.message)}</div>`).join('')||'<p class="tiny muted">No material changes recorded yet.</p>'}</details><div class="actions project-links"><button class="quiet" data-action="edit-project">Edit project context</button><button class="quiet" data-dialog="sourceDialog">Manage evidence</button><button class="quiet" data-action="delete-project">Delete project</button></div></article>`;}
function buildDraft(force=false){const p=project();if(!p)return;const action=()=>{E.generate(p,{buyer:p.story?.buyer,audience:p.story?.audience});save();switchView('stories');};if(p.story&&!force){switchView('stories');return;}if(!p.answers.some(x=>x.trim())){toast('Add at least one interview answer before creating a draft.');switchView('interview');return;}if(p.story?.edited)confirm('Replace your edited draft?','Updating from the interview replaces the story wording and clears both reviews. Your interview and sources are retained.',action);else action();}
function reviewHeader(p,draft=false){const ready=E.ready(p)&&!draft;return p.sample?(ready?'FICTIONAL EXAMPLE · REVIEWED LOCALLY · NOT CUSTOMER MATERIAL':'FICTIONAL EXAMPLE · DRAFT / UNVERIFIED'):ready?'REVIEWED LOCALLY · CONFIRM ORGANIZATIONAL PERMISSIONS BEFORE SHARING':'DRAFT / UNVERIFIED · NOT FOR CUSTOMER USE';}
function paperHTML(p,draft=false,exporting=false){const s=p.story;if(!s)return '';const localReady=E.ready(p)&&!draft,parts=s.parts;const dm=p.metric?E.metricDisplay(p.metric):null;const stale=s.sourceRevision!==p.recordRevision;const numberOk=!!dm&&!E.metricIssues(p.metric,p.sources).length&&!stale;const gap=v=>v.trim()?esc(v).replace(/\n/g,'<br>'):'<span class="muted">Not captured. Leave this open until the project owner can clarify it.</span>';const sources=p.sources.filter(x=>x.active);const sourceRef=i=>sources.filter(x=>x.topics.includes(i)).map(x=>`<span class="source-ref">${s.audience==='external'?'EVIDENCE '+(p.sources.indexOf(x)+1):esc(x.name)+' · '+esc(x.version)}</span>`).join(' ');
 return `<div class="status-banner ${localReady?'':'draft'}">${esc(reviewHeader(p,draft))}</div><div class="paper-head"><div class="paper-top"><img src="${window.ATLAS_LOGO}" alt="Mantu"><span>${esc(p.stage.toUpperCase())}<br>${esc(p.sector.toUpperCase())}</span></div><p class="eyebrow">${s.audience==='external'?'CUSTOMER CONVERSATION':'INTERNAL WORKING RECORD'}</p><h2>${esc(s.title)}</h2><p>${esc(p.consultant)}${p.role?' · '+esc(p.role):''}<br>Prepared for ${s.buyer==='operations'?'an':'a'} ${esc(E.BUYERS[s.buyer].label.toLowerCase())}. No future results are promised.</p></div><div class="paper-body">${numberOk?`<div class="outcome-block ${localReady?'measured':''}"><strong>${esc(dm.headline)}</strong><div><span>${esc(dm.label)}</span><span class="metric-status">${localReady?'Evidence reviewed locally':'Calculated from your entries · not verified'}</span></div></div>`:'<div class="outcome-block"><strong class="textual">'+(stale?'Draft needs updating':'The outcome, in context')+'</strong><span>'+(stale?'The record changed after this draft was created.':'No verified headline metric is being asserted.')+'</span></div>'}${window.AtlasCharts?AtlasCharts.dashboard(AtlasCharts.modelFromProject(p,E,{draft,exporting,audience:s.audience,sample:!!p.sample,gate:{numberOk,stale,localReady},jevAvailable:!!jevStatus}),{interactive:!exporting}):''}${[0,2,1,3,5].map(i=>`<h3>${esc(E.HEADINGS[i])}</h3><p>${gap(parts[i])} ${sourceRef(i)}</p>`).join('')}${s.audience==='internal'?`<h3>${esc(E.HEADINGS[4])}</h3><p>${gap(parts[4])}</p>`:''}<h3>A question for the next conversation</h3><p>${esc(E.BUYERS[s.buyer].question)}</p><p class="limits"><strong>Limits:</strong> ${esc(s.limitations||p.metric?.caveat||'Do not generalize this project into a promise of results. Confirm scope, comparability and permitted reuse with the project owner.')}${p.metric?' '+esc(p.metric.period)+'. '+esc(p.metric.scope)+'.':''}</p><div class="paper-footer">Story r${s.revision} · Record r${p.recordRevision} · Reference ${esc(E.fingerprint(p))} · ${s.audience==='external'?'Customer-facing scope':'Internal scope'}<br>${localReady?`Facts recorded by ${esc(s.review.facts.name)} (${esc(s.review.facts.role)}), ${esc(fmt(s.review.facts.at))}.`:'No completed local factual and permission review.'}<br>Local records are not centrally authenticated. Downloaded copies cannot be remotely recalled.${p.sample?'<br>All names, results and evidence in this example are fictional.':''}</div></div>`;}
function renderStory(){const p=project(),s=p?.story;const empty=!s;$('emptyStories').hidden=!empty;document.querySelector('.story-toolbar').hidden=empty;document.querySelector('.story-layout').hidden=empty;if(empty){$('emptyStories').innerHTML=p?'<h2>Give this project a story.</h2><p>Your draft will use the six interview answers. Unknowns stay open.</p><button class="btn primary" data-action="draft">Build from my answers →</button>':'<h2>Your next story starts with the work.</h2><p>Create a project and capture its context before drafting.</p><button class="btn primary" data-view="interview">Go to interview →</button>';return;}$('buyerSelect').value=s.buyer;$('audienceSelect').value=s.audience;$('storyRevision').textContent='Revision '+s.revision;$('storyPaper').innerHTML=paperHTML(p);window.AtlasCharts?.bind($('storyPaper'));const issues=E.evidenceIssues(p),f=s.review.facts,pm=s.review.permission;$('reviewName').value=f?.name||$('reviewName').dataset.savedName||'';$('reviewRole').value=f?.role||$('reviewRole').dataset.savedRole||'';$('permissionRef').value=pm?.reference||$('permissionRef').dataset.savedRef||'';$('factsCheck').checked=!!f;$('factsCheck').disabled=issues.length>0;$('permissionCheck').checked=!!pm;$('permissionCheck').disabled=!f||issues.length>0;$('exportStory').disabled=!E.ready(p);$('permissionCopy').textContent=s.audience==='external'?'Confirm the exact alias, wording, audience, account/client and Mantu brand permissions. A local checkbox is not corporate authorization.':'Confirm who may use this internal record and record its confidentiality and required permissions.';
 $('reviewState').innerHTML=issues.length?'<strong>Draft only · '+issues.length+' open item'+(issues.length===1?'':'s')+'</strong>'+issues.slice(0,3).map(i=>'<span class="review-gap">'+esc(i)+'</span>').join('')+(issues.length>3?'<span>Resolve the interview gaps and inspect sources covering each statement.</span>':''):E.ready(p)?'<strong>Locally reviewed copy available</strong><span>Review belongs to this exact version and audience. Confirm organizational permissions before sending.</span>':!f?'<strong>Evidence inspected. Confirm the facts.</strong><span>Enter the reviewer’s name and responsibility, then record the factual check.</span>':'<strong>Facts recorded. Permission still needed.</strong><span>Add a dated permission reference for this exact use.</span>';
 $('refreshDraft').textContent=s.sourceRevision!==p.recordRevision?'Update stale draft →':'Rebuild from interview';}
function renderSources(){const p=project();if(!p){$('sourceList').innerHTML='<p>Create a project before adding evidence.</p>';$('addSource').disabled=true;return;}$('addSource').disabled=p.sources.length>=20;$('sourceList').innerHTML=p.sources.length?p.sources.map((s,i)=>`<article class="source-card ${s.active?'':'inactive'}"><h3>${i+1}. ${esc(s.name)}</h3><p>${esc(s.version)} · ${s.active?s.inspected?'Inspected locally':'Not inspected':'Withdrawn'} · ${s.text.length.toLocaleString()} characters</p><div class="chips">${s.topics.map(t=>'<span>'+esc(E.TOPICS[t].label)+'</span>').join('')}</div><div class="actions">${s.active?`<button class="btn" data-inspect="${esc(s.id)}">Inspect excerpt</button><button class="quiet" data-edit-source="${esc(s.id)}">Edit</button>`:''}<button class="quiet" data-withdraw="${esc(s.id)}">${s.active?'Withdraw':'Restore as unreviewed'}</button><button class="quiet" data-delete-source="${esc(s.id)}">Delete</button></div></article>`).join(''):'<div class="empty-state"><h3>The story needs something a reviewer can check.</h3><p>Add an excerpt, a delivery record or a versioned measurement. One source may support several statements when appropriate.</p></div>';}
function editSource(sid=null){const p=project();if(!p)return;editingSourceId=sid;const s=p.sources.find(x=>x.id===sid);for(const [el,key] of [['sourceName','name'],['sourceVersion','version'],['sourceURL','url'],['sourceText','text']])$(el).value=s?.[key]||'';$('sourceTopics').innerHTML=[0,1,2,3,5].map(i=>`<label class="check"><input type="checkbox" name="sourceTopic" value="${i}" ${s?.topics.includes(i)?'checked':''}><span>${esc(E.TOPICS[i].label)}</span></label>`).join('');$('sourceEditTitle').textContent=s?'Edit supporting evidence.':'Add supporting evidence.';open('sourceEditDialog');}
function inspectSource(sid){const p=project(),s=p?.sources.find(x=>x.id===sid&&x.active);if(!s)return;inspectingId=sid;$('sourceInspectTitle').textContent=s.name;$('sourceInspectBody').innerHTML=`<p class="source-detail">${esc(s.version)} · Local content checksum ${esc(E.simpleHash(s.text))} (change detection, not proof of authenticity)</p>${s.url?`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Open original link ↗</a> <small class="muted">External site; not fetched by ATLAS</small></p>`:''}<div class="source-excerpt">${esc(s.text)}</div><p class="source-coverage">Supports: ${s.topics.map(i=>esc(E.TOPICS[i].label)).join(', ')}</p><p class="tiny muted">Check the exact passage, source version, attribution and limitations. This local inspection does not establish truth or permission to disclose.</p>`;open('sourceInspectDialog');}
function editMetric(){const p=project();if(!p)return;const m=p.metric;for(const [el,key] of [['metricName','name'],['metricUnit','unit'],['metricBefore','before'],['metricAfter','after'],['metricPeriod','period'],['metricScope','scope'],['metricCaveat','caveat']])$(el).value=m?.[key]??'';const eligible=p.sources.filter(s=>s.active&&s.topics.includes(3));$('metricSource').innerHTML='<option value="">Choose an outcome source</option>'+eligible.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.version)}</option>`).join('');$('metricSource').value=m?.sourceId||'';$('removeMetric').disabled=!m;if(!eligible.length)toast('Add evidence covering “The outcome” before saving a measurement.');open('metricDialog');}
function editStory(){const p=project(),s=p?.story;if(!s)return;$('editTitle').value=s.title;$('editLimits').value=s.limitations;$('storyEditFields').innerHTML=E.HEADINGS.map((h,i)=>`<div><label class="field-label" for="editPart${i}">${esc(h)}</label><textarea id="editPart${i}" maxlength="6000">${esc(s.parts[i])}</textarea></div>`).join('');open('editStoryDialog');}
function renderMemory(){const u=profile();$('userSelect').innerHTML=state.profiles.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('userSelect').value=u.id;$('memorySummary').innerHTML='<p class="memory-title">Local preferences · never inserted into story text</p>'+(u.preferences.length?u.preferences.map((m,i)=>`<div class="memory-row"><p>${esc(m)}</p><button class="quiet" data-forget="${i}">Forget</button></div>`).join(''):'<p class="small muted">No preferences recorded.</p>')+(project()?`<p class="memory-title">Resume</p><p class="small muted">${esc(project().title)} · ${Math.min(6,project().pos+1)} / 6 topics visited</p>`:'');$('memoryInput').value='';$('storageDetail').textContent=persisted?'Device autosave is enabled. This browser holds an unencrypted local copy. It is not Hindsight or cloud sync.':'Session-only mode. Export a backup or enable autosave before closing this tab.';$('toggleStorage').textContent=persisted?'Remove saved copy · use session only':'Enable device autosave';}
function backup(){clearTimeout(saveTimer);if(!blocked)saveNow();const out={format:'atlas-workspace',schema:4,exportedAt:E.now(),notice:'Unencrypted local workspace backup. Imported source inspections and approvals will be cleared.',profile:profile()};download('ATLAS_'+slug(profile().name)+'_backup.json',JSON.stringify(out,null,2),'application/json');toast('Workspace backup exported. It includes sources and preferences; store it securely.');}
function storyText(p,md=true,draft=true){const s=p.story;const pre=md?'# ':'';let out=pre+s.title+'\n\n'+reviewHeader(p,draft)+'\n\n'+[p.stage,p.sector,p.consultant,p.role].filter(Boolean).join(' · ')+'\n\n';if(p.metric&&s.sourceRevision===p.recordRevision&&!E.metricIssues(p.metric,p.sources).length){const d=E.metricDisplay(p.metric);out+=(md?'## ':'')+'Recorded measurement\n'+d.headline+' · '+d.label+'\n'+(E.ready(p)&&!draft?'Reviewed locally.':'Calculated from entered values, not verified.')+'\n\n';}if(window.AtlasCharts)out+=AtlasCharts.textSummary(AtlasCharts.modelFromProject(p,E,{draft,audience:s.audience,sample:!!p.sample}),md)+'\n';for(const i of [0,2,1,3,5])out+=(md?'## ':'')+E.HEADINGS[i]+'\n'+(s.parts[i].trim()||'[Not captured]')+'\n\n';if(s.audience==='internal')out+=(md?'## ':'')+E.HEADINGS[4]+'\n'+(s.parts[4]||'[Not captured]')+'\n\n';out+=(md?'## ':'')+'A question for the next conversation\n'+E.BUYERS[s.buyer].question+'\n\n'+(md?'## ':'')+'Limitations\n'+(s.limitations||p.metric?.caveat||'Confirm scope and permitted reuse. No future result is guaranteed.')+'\n\n';if(p.metric)out+='Comparison: '+p.metric.period+'. '+p.metric.scope+'.\n\n';out+='Story r'+s.revision+' · Record r'+p.recordRevision+' · Reference '+E.fingerprint(p)+'\nLocal records are not authenticated corporate approvals. Downloaded copies cannot be recalled.\n';return out;}
const exportCSS=(window.AtlasCharts?AtlasCharts.EXPORT_CSS:'')+`:root{--p:#3E007A;--y:#F6EB4B;--g1:#F8F8F8;--g2:#E8E8EE;--g3:#D6D6D6;--g5:#666A78;--g6:#2F3440}*{box-sizing:border-box}body{margin:0;background:var(--g1);font:14px/1.8 Arial,sans-serif;color:#101011}main{max-width:900px;margin:25px auto;background:white;border:1px solid var(--g2)}.status-banner{padding:16px 30px;font-size:11px;background:var(--g1);color:var(--p)}.status-banner.draft{background:var(--y)}.paper-head{background:var(--p);color:white;padding:34px}.paper-top{display:flex;justify-content:space-between;gap:20px;font-size:10px}.paper-top img{width:125px;height:auto;align-self:flex-start}.eyebrow{font-size:10px;color:var(--y);letter-spacing:1.2px;margin-top:25px}h2{font-size:35px;font-weight:500;line-height:1.18;overflow-wrap:anywhere}h3{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:var(--p);margin:24px 0 7px}.paper-body{padding:30px 34px}.paper-body p{overflow-wrap:anywhere}.outcome-block{border:1px solid var(--g2);padding:20px;display:flex;align-items:center;gap:20px;flex-wrap:wrap;border-radius:10px}.outcome-block strong{font-size:32px;color:var(--p)}.outcome-block strong.textual{font-size:20px}.outcome-block span{font-size:12px;display:block}.outcome-block.measured{background:var(--y)}.metric-status{font-size:10px!important}.source-ref{font-size:9px;border:1px solid var(--g2);border-radius:4px;padding:2px 4px;color:var(--g5)}.limits{border-left:3px solid var(--p);padding-left:15px;font-size:12px;color:var(--g5)}.paper-footer{border-top:1px solid var(--g2);padding-top:15px;font-size:10px;color:var(--g5)}@media(max-width:600px){main{margin:0;border:0}.paper-head,.paper-body{padding:25px 22px}h2{font-size:30px}}@media print{main{margin:0;border:0}.paper-head,.status-banner,.measured{print-color-adjust:exact;-webkit-print-color-adjust:exact}.paper-head,.outcome-block{break-inside:avoid}h3{break-after:avoid}@page{size:A4;margin:15mm}}`;
function exportStory(draft=true){const p=project();if(!p?.story)return;if(!draft&&!E.ready(p)){toast('Reviewed export is blocked until the current version has both recorded decisions.');return;}const format=$('exportFormat').value,base='ATLAS_'+slug(p.story.title)+'_'+(draft?'DRAFT':'LOCAL-REVIEW')+'_r'+p.story.revision;let content;if(format==='html'){content=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; object-src 'none'; base-uri 'none'; form-action 'none'"><title>${esc(p.story.title)}</title><style>${exportCSS}</style></head><body><main>${paperHTML(p,draft,true)}</main></body></html>`;}else content=storyText(p,format==='md',draft);download(base+'.'+format,content,format==='html'?'text/html':format==='md'?'text/markdown':'text/plain');E.log(p,(draft?'Draft':'Locally reviewed copy')+' exported as '+format);save();toast('Exported '+(draft?'a clearly marked draft.':'a locally reviewed copy. Confirm permissions before external use.'));}
function clearReviewInputs(){for(const el of ['reviewName','reviewRole','permissionRef']){const n=$(el);n.value='';delete n.dataset.savedName;delete n.dataset.savedRole;delete n.dataset.savedRef;}}
function addSample(){if(state.profiles.length>=10){toast('Workspace limit reached (10). Remove a workspace before adding the example.');return;}const u=E.blankProfile('Fictional example');u.preferences=['Ask for the business context before the technology.'];const p=E.project({title:'Making service-ticket triage more consistent',consultant:'Maya Laurent',role:'Data engineer',sector:'Financial services',stage:'Pilot',sample:true});p.answers=[
 'A fictional operations team routed service tickets using inconsistent intake categories. Manual interpretation made triage difficult to standardize. The eight-week pilot covered one queue; enterprise-wide rollout was outside scope.',
 'I built the Python ingestion pipeline and normalization rules. Theo tested routing behavior and exception cases. The lead architect owned target architecture; I did not own the wider solution design.',
 'We chose explicit categories and routing rules rather than an autonomous agent. Operations staff tested the exceptions, agreed escalation owners and adopted the pilot workflow. The service owner took responsibility after handover.',
 'The fictional worksheet records a median triage duration of 42 minutes in the baseline and 26 minutes in the pilot, with 180 tickets in each cohort. This is a before-and-after observation, not proof of causality or financial savings.',
 'Synthetic pilot acceptance record v1 includes the roles, scope, routing approach and a measurement worksheet. A delivery reviewer must inspect the values and limitations. There is no evidence of production-wide savings.',
 'This example is relevant to operations leaders with inconsistent service queues and a comparable baseline. It is a poor fit where intake cannot be standardized or local ownership is missing. Disclosure, account and brand permission must be resolved before any customer reuse.'
 ];p.sources=[{id:E.id(),name:'Synthetic pilot acceptance record',version:'v1 · 2026-08-28',url:'',active:true,inspected:false,topics:[0,1,2,3,5],text:'FICTIONAL DEMONSTRATION — NOT A CLIENT RECORD.\n\nContext: one financial-services service queue with inconsistent manual intake categories. Eight-week pilot; no enterprise rollout.\nContribution: Maya implemented ingestion and normalization. Theo tested routing and exceptions. The lead architect owned architecture.\nApproach: explicit categories and routing rules were preferred over an autonomous agent. Operations staff tested exceptions and a service owner accepted handover.\nBaseline: 42-minute median triage duration, 180 tickets, 1–28 June 2026.\nPilot: 26-minute median triage duration, 180 tickets, 1–28 August 2026.\nLimitations: different time windows; case mix and staffing may differ. No causal attribution, financial ROI, or enterprise-wide outcome established.\nApplicability: comparable service queues with local process ownership. Poor fit if intake cannot be standardized. No external permission has been recorded.'}];p.metric={name:'Median triage duration',unit:'minutes',before:42,after:26,period:'1–28 June 2026 baseline; 1–28 August 2026 pilot',scope:'180 tickets in each cohort; one fictional service queue',caveat:'Different periods; case mix and staffing may differ. This observation does not establish causality, financial ROI or an enterprise-wide result.',sourceId:p.sources[0].id};p.pos=0;E.generate(p);E.log(p,'Fictional example loaded into a separate local workspace');u.projects=[p];u.lastProject=p.id;state.profiles.push(u);state.activeProfile=u.id;clearReviewInputs();save();switchView('interview');toast('Fictional example opened separately. Your own workspace is unchanged.');}
// UI bindings. No arbitrary source HTML or imported scripts are executed.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(blocked&&!b.hasAttribute('data-close')&&!['backupProfile','backupQuick'].includes(b.id)&&!b.closest('#blockingNotice')){toast('Editing is paused. Export a backup, then reload.');return;}if(b.dataset.view)switchView(b.dataset.view);if(b.dataset.dialog){if(b.dataset.dialog==='sourceDialog'&&!project()){toast('Create a project first.');return;}open(b.dataset.dialog);}if(b.hasAttribute('data-close'))b.closest('dialog')?.close();if(b.dataset.step!==undefined&&project()){stopVoice();project().pos=Number(b.dataset.step);editToken=null;save();renderInterview();}
 if(b.dataset.project){clearReviewInputs();selectProject(b.dataset.project);}if(b.dataset.inspect)inspectSource(b.dataset.inspect);if(b.dataset.editSource)editSource(b.dataset.editSource);
 if(b.dataset.withdraw){const p=project(),s=p?.sources.find(x=>x.id===b.dataset.withdraw);if(s)confirm(s.active?'Withdraw this source?':'Restore this source?','Both story reviews will be cleared. A restored source needs a fresh inspection.',()=>{s.active=!s.active;s.inspected=false;changed(p,s.active?'Restored source as unreviewed':'Withdrew source');renderSources();render();});}
 if(b.dataset.deleteSource){const p=project(),s=p?.sources.find(x=>x.id===b.dataset.deleteSource);if(s)confirm('Delete source permanently?','The stored excerpt will be removed from this workspace. Any linked metric becomes unresolved and story reviews are cleared.',()=>{p.sources=p.sources.filter(x=>x.id!==s.id);changed(p,'Deleted supporting source');renderSources();render();});}
 if(b.dataset.forget!==undefined){profile().preferences.splice(Number(b.dataset.forget),1);save();renderMemory();if(view==='interview')renderOutline();}
 const action=b.dataset.action;if(action==='new-project')newProject();if(action==='edit-project')newProject(true);if(action==='draft')buildDraft();if(action==='metric')editMetric();if(action==='sample')addSample();if(action==='reset-search'){$('projectSearch').value='';$('stageFilter').value='all';$('categoryFilter').value='all';$('projectSort').value='recent';renderProjects();}if(action==='delete-project'){const p=project();if(p)confirm('Delete this project?','This removes the project, its source excerpts, draft and local review history. Export a backup first to keep a copy.',()=>{profile().projects=profile().projects.filter(x=>x.id!==p.id);profile().lastProject=profile().projects[0]?.id||null;clearReviewInputs();save();render();});}
});
$('answerInput').addEventListener('input',e=>answerInput(e.target.value));$('answerInput').addEventListener('blur',()=>{editToken=null;});$('answerInput').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();next();}});
